const $=id=>document.getElementById(id);
let state={board:Array(225).fill(0),history:[],winner:0,line:[],draw:false,turn:1,players:[null,null],pending:null,startedAt:null,elapsed:0};
let session=null,stream=null,connected=false,busy=false,entering=false;const cells=[];
try{session=JSON.parse(sessionStorage.getItem('gomoku-room'));if(!session?.code||!session?.token||![1,2].includes(session.color))session=null}catch{}
const invited=new URLSearchParams(location.search).get('room');if(/^\d{6}$/.test(invited||''))$('room-code').value=invited;
function error(message){$('error').textContent=message;$('error').hidden=!message}
async function api(url,data,auth=true){const response=await fetch(url,{method:data===undefined?'GET':'POST',headers:{'Content-Type':'application/json',...(auth&&session?{Authorization:'Bearer '+session.token}:{})},...(data===undefined?{}:{body:JSON.stringify(data)})});const result=await response.json();if(!response.ok)throw new Error(result.error||'连接失败，请重试');return result}
function remember(){try{if(session)sessionStorage.setItem('gomoku-room',JSON.stringify(session));else sessionStorage.removeItem('gomoku-room')}catch{}}
async function enter(code){if(entering)return;entering=true;$('create-room').disabled=true;$('join-form').querySelector('button').disabled=true;error('');try{const result=await api(code?`/api/rooms/${code}/join`:'/api/rooms',{},false);session={code:result.code,token:result.token,color:result.color};state=result.state;remember();connect()}catch(e){error(e.message)}finally{entering=false;$('create-room').disabled=false;$('join-form').querySelector('button').disabled=false}}
function connect(){stream?.close();connected=false;render();const active=session;stream=new EventSource(`/api/rooms/${active.code}/events?token=${encodeURIComponent(active.token)}`);stream.onmessage=e=>{if(session!==active)return;state=JSON.parse(e.data);connected=true;render()};stream.onerror=async()=>{if(session!==active)return;connected=false;render();try{const response=await fetch(`/api/rooms/${active.code}/state`,{headers:{Authorization:'Bearer '+active.token}});if(session===active&&[401,404].includes(response.status)){stream.close();const result=await response.json();error(result.error+'。可以返回大厅重新创建。')}}catch{}}}
async function action(data){if(busy||!session||!connected)return false;busy=true;error('');try{state=await api(`/api/rooms/${session.code}/action`,data);render();return true}catch(e){error(e.message);return false}finally{busy=false}}
function canPlay(){return !!session&&connected&&state.players.every(p=>p?.online)&&!state.winner&&!state.draw&&!state.pending&&state.turn===session.color}
for(let row=0;row<15;row++)for(let col=0;col<15;col++){const cell=document.createElement('button');cell.type='button';cell.className='cell'+(row===0?' top':'')+(row===14?' bottom':'')+(col===0?' left':'')+(col===14?' right':'')+([[3,3],[3,11],[7,7],[11,3],[11,11]].some(([r,c])=>r===row&&c===col)?' star':'');cell.setAttribute('role','gridcell');cell.tabIndex=row===7&&col===7?0:-1;cell.addEventListener('click',()=>{if(canPlay())action({type:'move',row,col})});cell.addEventListener('keydown',e=>{const d={ArrowLeft:[0,-1],ArrowRight:[0,1],ArrowUp:[-1,0],ArrowDown:[1,0]}[e.key];if(!d)return;e.preventDefault();focusCell(Math.max(0,Math.min(14,row+d[0]))*15+Math.max(0,Math.min(14,col+d[1])))});cells.push(cell);$('board').append(cell)}
function focusCell(i){cells.forEach(c=>c.tabIndex=-1);cells[i].tabIndex=0;cells[i].focus()}
function render(){const numbers=$('numbers').checked;$('board').classList.toggle('show-numbers',numbers);const last=state.history.at(-1);cells.forEach((cell,i)=>{const color=state.board[i];const order=color?state.history.findIndex(m=>m.row*15+m.col===i)+1:0;const key=color+':'+(numbers?order:'');if(cell.dataset.piece!==key){cell.dataset.piece=key;cell.replaceChildren();if(color){const stone=document.createElement('span');stone.className='stone '+(color===1?'black':'white');if(numbers)stone.textContent=order;cell.append(stone)}}cell.classList.toggle('occupied',!!color);cell.classList.toggle('latest',!!last&&i===last.row*15+last.col);cell.classList.toggle('winner',state.line.includes(i));cell.setAttribute('aria-label',`${Math.floor(i/15)+1}行${i%15+1}列，${color?(color===1?'黑棋':'白棋'):'空位'}`);cell.setAttribute('aria-disabled',String(!!color||!canPlay()))});
 const done=state.winner||state.draw,ready=state.players.every(p=>p?.online);
 $('lobby').hidden=!!session;$('room-info').hidden=!session;
 if(session){$('my-color').textContent=session.color===1?'你执黑棋 · 先行':'你执白棋 · 后手';$('room-label').textContent='房间 '+session.code}
 $('connection').textContent=!session?'创建房间后即可邀请好友':!connected?'连接中，断线后将自动重连…':!state.players[1]?'等待好友加入房间':!ready?'对方已断线，等待重新连接':'双方已连接 · 实时同步';
 $('phase').textContent=done?'本局结束':!session?'准备对弈':!ready?'等待对手':state.turn===session.color?'轮到你了':'请稍候';
 $('status').textContent=state.winner?(state.winner===1?'黑方获胜！':'白方获胜！'):state.draw?'棋逢对手，平局':!session?'棋盘已就绪':!ready?'等待对手连接':(state.turn===1?'黑方落子':'白方落子');
 $('hint').textContent=!session?'创建房间，邀请好友开始对弈。':done?'再来一局？向对方发起新局邀请。':!ready?'把房间码发给好友，在各自的设备上下棋。':state.pending?'先处理请求，再继续对弈。':state.turn===session.color?'点击空白交叉点，落下你的下一手。':'对方正在思考，静候好棋。';
 $('black-player').classList.toggle('active',!!session&&ready&&!done&&state.turn===1);$('white-player').classList.toggle('active',!!session&&ready&&!done&&state.turn===2);
 $('moves').textContent=String(state.history.length).padStart(2,'0');$('undo').disabled=$('restart').disabled=!session||!connected||!ready||!state.history.length||!!state.pending;
 $('last-move').textContent=last?`上一手 · ${last.row+1}行 ${last.col+1}列`:'等待第一手';
 $('request-box').hidden=!state.pending||!session;if(state.pending&&session){const own=state.pending.by===session.color;$('request-text').textContent=(own?'已向对方请求':'对方请求')+(state.pending.kind==='undo'?'撤回最近一步':'重新开始本局')+(own?'，等待同意。':'，是否同意？');$('accept').hidden=$('reject').hidden=own;$('cancel-request').hidden=!own}
 tick();
}
function tick(){const seconds=Math.max(0,Math.floor((state.startedAt===null?state.elapsed:Date.now()-state.startedAt)/1000));$('time').textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0')}
$('create-room').onclick=()=>enter();$('join-form').onsubmit=e=>{e.preventDefault();const code=$('room-code').value.trim();if(/^\d{6}$/.test(code))enter(code);else error('请输入6位数字房间码')};
$('undo').onclick=()=>action({type:'request',kind:'undo'});$('restart').onclick=()=>action({type:'request',kind:'restart'});$('accept').onclick=()=>action({type:'respond',accept:true});$('reject').onclick=()=>action({type:'respond',accept:false});$('cancel-request').onclick=()=>action({type:'cancel'});$('numbers').onchange=render;
$('copy-code').onclick=async()=>{try{await navigator.clipboard.writeText(session.code);$('copy-code').textContent='已复制';setTimeout(()=>$('copy-code').textContent='复制房间码',1800)}catch{error('房间码为 '+session.code+'，请长按或选中复制。')}};
$('leave-room').onclick=()=>{if(!window.confirm('返回大厅后将离开当前座位，无法通过房间码找回此座位。确认离开？'))return;stream?.close();session=null;connected=false;remember();state={board:Array(225).fill(0),history:[],winner:0,line:[],draw:false,turn:1,players:[null,null],pending:null,startedAt:null,elapsed:0};error('');render()};
api('/api/info',undefined,false).then(info=>{const box=$('lan-addresses');box.replaceChildren();for(const address of info.addresses){const a=document.createElement('a');a.href=address;a.textContent=address;box.append(a)}if(!info.addresses.length)box.textContent='暂未检测到局域网地址，请连接 Wi-Fi 后刷新。'}).catch(()=>{$('lan-addresses').textContent='请先双击启动网站，再通过本机网址访问。'});
setInterval(tick,1000);render();if(session)connect();
